const std = @import("std");

fn buildLPS(pattern: []const u8, lps: []usize) void {
    var len: usize = 0;
    var i: usize = 1;
    while (i < pattern.len) {
        if (pattern[i] == pattern[len]) {
            len += 1;
            lps[i] = len;
            i += 1;
        } else if (len != 0) {
            len = lps[len - 1];
        } else {
            lps[i] = 0;
            i += 1;
        }
    }
}

fn search(text: []const u8, pattern: []const u8) void {
    var lps: [10]usize = [_]usize{0} ** 10;
    buildLPS(pattern, lps);
    var i: usize = 0;
    var j: usize = 0;
    while (i < text.len) {
        if (text[i] == pattern[j]) { i += 1; j += 1; }
        if (j == pattern.len) {
            std.debug.print("Found at {}\n", .{i - j});
            j = lps[j - 1];
        } else if (i < text.len and text[i] != pattern[j]) {
            if (j != 0) j = lps[j - 1] else i += 1;
        }
    }
}

pub fn main() !void {
    const text = "ABCABCDABABCDABCDABDE";
    const pattern = "ABCDABD";
    search(text, pattern);
}

